sys_ui_page.client_script:
function onOK() {
	var sysId = g_form.getUniqueValue();
	updateField(sysId, 'state', '7');
	GlideDialogWindow.get().destroy();
}

function onCancel() {
	GlideDialogWindow.get().destroy();
}

//Ajax
function updateField(sysId, fieldName, fieldValue) {
    var ga = new GlideAjax('FieldUpdater');
    ga.addParam('sysparm_name', 'updateField');
    ga.addParam('sysparm_sys_id', sysId);
    ga.addParam('sysparm_field_name', fieldName);
    ga.addParam('sysparm_field_value', fieldValue);
    ga.getXMLAnswer(function(response) {if (response === 'success') {

    alert('State Field updated successfully');
	} else {	
	alert('State Field updated failed');

}});
}
